// src/services/task-scheduler.ts
var registry2 = new Map;
var dirtyAgents = new Set;
var adapter = null;
function registerTaskSchedulerRuntime(runtime2, taskService) {
  const agentIdKey = String(runtime2.agentId);
  registry2.set(agentIdKey, { runtime: runtime2, taskService });
  dirtyAgents.add(agentIdKey);
}
function unregisterTaskSchedulerRuntime(agentId) {
  registry2.delete(String(agentId));
}
function markTaskSchedulerDirty(agentId) {
  dirtyAgents.add(String(agentId));
}
function getTaskSchedulerAdapter() {
  return adapter;
}

// src/services/task.ts
function resolveDueTime(task2) {
  if (task2.dueAt != null) {
    if (typeof task2.dueAt === "number")
      return task2.dueAt;
    if (typeof task2.dueAt === "bigint")
      return Number(task2.dueAt);
    return new Date(String(task2.dueAt)).getTime();
  }
  const scheduledAt = task2.metadata?.scheduledAt;
  if (scheduledAt == null)
    return null;
  if (typeof scheduledAt === "number")
    return scheduledAt;
  const t = new Date(scheduledAt).getTime();
  return Number.isNaN(t) ? null : t;
}

class TaskService extends Service {
  timer = null;
  TICK_INTERVAL = 1000;
  executingTasks = new Set;
  tasksDirty = true;
  stopped = false;
  static serviceType = ServiceType2.TASK;
  capabilityDescription = "The agent is able to schedule and execute tasks";
  static async start(runtime2) {
    const service3 = new TaskService(runtime2);
    runtime2.registerTaskWorker({
      name: "BATCHER_DRAIN",
      execute: async (rt, options) => {
        const affinityKey = options.affinityKey;
        if (!rt.promptBatcher || !affinityKey)
          return;
        await rt.promptBatcher.drainAffinityGroup(affinityKey);
        return;
      }
    });
    await service3.startTimer();
    return service3;
  }
  async createTestTasks() {
    this.runtime.registerTaskWorker({
      name: "REPEATING_TEST_TASK",
      validate: async (_runtime, _message, _state2) => {
        this.runtime.logger.debug({
          src: "plugin:basic-capabilities:service:task",
          agentId: this.runtime.agentId
        }, "Validating repeating test task");
        return true;
      },
      execute: async (_runtime, _options) => {
        this.runtime.logger.debug({
          src: "plugin:basic-capabilities:service:task",
          agentId: this.runtime.agentId
        }, "Executing repeating test task");
        return;
      }
    });
    this.runtime.registerTaskWorker({
      name: "ONETIME_TEST_TASK",
      validate: async (_runtime, _message, _state2) => {
        this.runtime.logger.debug({
          src: "plugin:basic-capabilities:service:task",
          agentId: this.runtime.agentId
        }, "Validating one-time test task");
        return true;
      },
      execute: async (_runtime, _options) => {
        this.runtime.logger.debug({
          src: "plugin:basic-capabilities:service:task",
          agentId: this.runtime.agentId
        }, "Executing one-time test task");
        return;
      }
    });
    const tasks = await this.runtime.getTasksByName("REPEATING_TEST_TASK");
    if (tasks.length === 0) {
      await this.runtime.createTask({
        name: "REPEATING_TEST_TASK",
        description: "A test task that repeats every minute",
        metadata: {
          updatedAt: Date.now(),
          updateInterval: 1000 * 60
        },
        tags: ["queue", "repeat", "test"]
      });
    }
    await this.runtime.createTask({
      name: "ONETIME_TEST_TASK",
      description: "A test task that runs once",
      metadata: {
        updatedAt: Date.now()
      },
      tags: ["queue", "test"]
    });
  }
  startTimer() {
    if (this.runtime.serverless === true) {
      return;
    }
    if (getTaskSchedulerAdapter() != null) {
      registerTaskSchedulerRuntime(this.runtime, this);
      return;
    }
    if (this.timer) {
      clearInterval(this.timer);
    }
    this.timer = setInterval(async () => {
      await this.checkTasks();
    }, this.TICK_INTERVAL);
  }
  async validateTasks(tasks) {
    const validatedTasks = [];
    for (const task2 of tasks) {
      if (!task2.id) {
        continue;
      }
      const worker = this.runtime.getTaskWorker(task2.name);
      if (!worker) {
        continue;
      }
      if (worker.shouldRun) {
        const shouldRun = await worker.shouldRun(this.runtime, task2);
        if (!shouldRun) {
          continue;
        }
      } else if (worker.validate) {
        const isValid2 = await worker.validate(this.runtime, {}, {});
        if (!isValid2) {
          continue;
        }
      }
      validatedTasks.push(task2);
    }
    return validatedTasks;
  }
  async checkTasks() {
    if (!this.tasksDirty) {
      return;
    }
    this.tasksDirty = false;
    const allTasks = await this.runtime.getTasks({
      tags: ["queue"],
      agentIds: [this.runtime.agentId]
    });
    if (!allTasks) {
      return;
    }
    await this.runTick(allTasks);
  }
  async runTick(tasks) {
    if (this.stopped)
      return;
    const validated = await this.validateTasks(tasks);
    const now = Date.now();
    for (const task2 of validated) {
      if (!task2.tags?.includes("repeat")) {
        const dueMs = resolveDueTime(task2);
        if (dueMs != null && now < dueMs)
          continue;
        await this.executeTask(task2);
        continue;
      }
      if (task2.metadata?.paused === true) {
        continue;
      }
      let lastRan;
      if (task2.metadata?.updatedAt != null && typeof task2.metadata.updatedAt === "number") {
        lastRan = task2.metadata.updatedAt;
      } else if (typeof task2.updatedAt === "number") {
        lastRan = task2.updatedAt;
      } else if (typeof task2.updatedAt === "bigint") {
        lastRan = Number(task2.updatedAt);
      } else if (task2.updatedAt) {
        lastRan = new Date(String(task2.updatedAt)).getTime();
      } else {
        lastRan = 0;
      }
      const taskMetadata = task2.metadata;
      const updateIntervalMs = taskMetadata?.updateInterval ?? 0;
      const notBeforeMs = taskMetadata?.notBefore ?? 0;
      const notAfterMs = taskMetadata?.notAfter;
      const idealNextRun = lastRan + updateIntervalMs;
      const earliest = idealNextRun - notBeforeMs;
      if (now < earliest) {
        continue;
      }
      if (notAfterMs != null && typeof notAfterMs === "number" && now > idealNextRun + notAfterMs) {
        this.runtime.logger.warn({
          src: "plugin:basic-capabilities:service:task",
          agentId: this.runtime.agentId,
          taskName: task2.name,
          taskId: task2.id,
          overdueMs: now - (idealNextRun + notAfterMs)
        }, "Task overdue");
      }
      const isBlocking = task2.metadata?.blocking !== false;
      if (isBlocking && task2.id && this.executingTasks.has(task2.id)) {
        this.runtime.logger.debug({
          src: "plugin:basic-capabilities:service:task",
          agentId: this.runtime.agentId,
          taskName: task2.name,
          taskId: task2.id
        }, "Skipping task - already executing (blocking enabled)");
        continue;
      }
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:task",
        agentId: this.runtime.agentId,
        taskName: task2.name,
        intervalMs: updateIntervalMs
      }, "Executing task - interval elapsed");
      await this.executeTask(task2);
    }
  }
  async executeTask(task2) {
    if (!task2?.id) {
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:task",
        agentId: this.runtime.agentId
      }, "Task not found");
      return;
    }
    const worker = this.runtime.getTaskWorker(task2.name);
    if (!worker) {
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:task",
        agentId: this.runtime.agentId,
        taskName: task2.name
      }, "No worker found for task type");
      return;
    }
    this.executingTasks.add(task2.id);
    const startTime = Date.now();
    try {
      const taskOptions = task2.metadata ?? {};
      const result = await worker.execute(this.runtime, taskOptions, task2);
      if (task2.tags?.includes("repeat")) {
        const meta3 = task2.metadata;
        const baseInterval = meta3?.baseInterval ?? meta3?.updateInterval;
        const newMeta = {
          ...meta3,
          updatedAt: Date.now(),
          failureCount: 0,
          lastError: undefined
        };
        const nextInterval = result != null && typeof result === "object" && "nextInterval" in result ? result.nextInterval : undefined;
        if (nextInterval != null) {
          newMeta.updateInterval = nextInterval;
        } else if (baseInterval != null && typeof baseInterval === "number") {
          newMeta.updateInterval = baseInterval;
        }
        await this.runtime.updateTask(task2.id, { metadata: newMeta });
      } else {
        await this.runtime.deleteTask(task2.id);
        this.runtime.logger.debug({
          src: "plugin:basic-capabilities:service:task",
          agentId: this.runtime.agentId,
          taskName: task2.name,
          taskId: task2.id
        }, "Deleted non-repeating task after execution");
      }
    } catch (error48) {
      if (task2.tags?.includes("repeat")) {
        const failureCount = (task2.metadata?.failureCount ?? 0) + 1;
        const rawMax = task2.metadata?.maxFailures;
        const neverPause = rawMax === Infinity || rawMax === -1;
        const maxFailures = neverPause ? Infinity : rawMax ?? 5;
        const newMeta = {
          ...task2.metadata,
          updatedAt: Date.now(),
          failureCount,
          lastError: error48 instanceof Error ? error48.message : String(error48)
        };
        if (!neverPause && failureCount >= maxFailures) {
          newMeta.paused = true;
          this.runtime.logger.warn({
            taskName: task2.name,
            taskId: task2.id,
            failureCount
          }, "Task auto-paused after max failures");
        } else {
          const baseInterval = task2.metadata?.baseInterval ?? task2.metadata?.updateInterval ?? 1000;
          newMeta.updateInterval = Math.min(baseInterval * 2 ** failureCount, 300000);
        }
        await this.runtime.updateTask(task2.id, { metadata: newMeta });
      } else if (task2.id) {
        await this.runtime.deleteTask(task2.id);
        this.runtime.logger.debug({
          src: "plugin:basic-capabilities:service:task",
          agentId: this.runtime.agentId,
          taskName: task2.name,
          taskId: task2.id
        }, "Deleted non-repeating task after execution failure");
      }
      this.runtime.logger.error({ taskName: task2.name, taskId: task2.id, error: error48 }, "Task execution failed");
    } finally {
      this.executingTasks.delete(task2.id);
      const durationMs = Date.now() - startTime;
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:task",
        agentId: this.runtime.agentId,
        taskName: task2.name,
        taskId: task2.id,
        durationMs
      }, "Task execution completed");
    }
  }
  markDirty() {
    if (getTaskSchedulerAdapter() != null) {
      markTaskSchedulerDirty(this.runtime.agentId);
      return;
    }
    this.tasksDirty = true;
  }
  async runDueTasks() {
    const allTasks = await this.runtime.getTasks({
      tags: ["queue"],
      agentIds: [this.runtime.agentId]
    });
    if (allTasks?.length) {
      await this.runTick(allTasks);
    }
  }
  async executeTaskById(taskId) {
    const task2 = await this.runtime.getTask(taskId);
    if (!task2) {
      throw new Error(`Task ${taskId} not found`);
    }
    await this.executeTask(task2);
  }
  async pauseTask(taskId) {
    const task2 = await this.runtime.getTask(taskId);
    if (!task2) {
      throw new Error(`Task ${taskId} not found`);
    }
    await this.runtime.updateTask(taskId, {
      metadata: { ...task2.metadata, paused: true }
    });
  }
  async resumeTask(taskId, runImmediately) {
    const task2 = await this.runtime.getTask(taskId);
    if (!task2) {
      throw new Error(`Task ${taskId} not found`);
    }
    await this.runtime.updateTask(taskId, {
      metadata: { ...task2.metadata, paused: false }
    });
    if (runImmediately) {
      const updated = await this.runtime.getTask(taskId);
      if (updated) {
        await this.executeTask(updated);
      }
    }
  }
  async getTaskStatus(taskId) {
    const task2 = await this.runtime.getTask(taskId);
    if (!task2) {
      return { task: null, paused: false, executing: false };
    }
    const paused = task2.metadata?.paused === true;
    const executing = task2.id ? this.executingTasks.has(task2.id) : false;
    let nextRunAt;
    if (task2.tags?.includes("repeat")) {
      let lastRan;
      const meta3 = task2.metadata;
      if (meta3?.updatedAt != null && typeof meta3.updatedAt === "number") {
        lastRan = meta3.updatedAt;
      } else if (typeof task2.updatedAt === "number") {
        lastRan = task2.updatedAt;
      } else if (typeof task2.updatedAt === "bigint") {
        lastRan = Number(task2.updatedAt);
      } else {
        lastRan = 0;
      }
      const interval = meta3?.updateInterval ?? 0;
      const notBefore = meta3?.notBefore ?? 0;
      nextRunAt = lastRan + interval - notBefore;
    }
    return {
      task: task2,
      paused,
      executing,
      nextRunAt,
      lastError: task2.metadata?.lastError
    };
  }
  static async stop(runtime2) {
    const service3 = runtime2.getService(ServiceType2.TASK);
    if (service3) {
      await service3.stop();
    }
  }
  async stop() {
    this.stopped = true;
    unregisterTaskSchedulerRuntime(this.runtime.agentId);
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    this.executingTasks.clear();
  }
}

