async function ensureFormattingEntities(runtime2, entities, messages) {
  const entitiesById = new Map;
  for (const entity of entities) {
    if (entity.id) {
      entitiesById.set(entity.id, entity);
    }
  }
  const missingMessageByEntityId = new Map;
  for (const memory2 of messages) {
    if (!memory2.entityId || entitiesById.has(memory2.entityId)) {
      continue;
    }
    if (!missingMessageByEntityId.has(memory2.entityId)) {
      missingMessageByEntityId.set(memory2.entityId, memory2);
    }
  }
  const missingEntityIds = Array.from(missingMessageByEntityId.keys());
  if (missingEntityIds.length === 0) {
    return Array.from(entitiesById.values());
  }
  const resolvedEntities = await Promise.all(missingEntityIds.map((entityId) => runtime2.getEntityById(entityId)));
  for (let i3 = 0;i3 < missingEntityIds.length; i3 += 1) {
    const entityId = missingEntityIds[i3];
    const resolvedEntity = resolvedEntities[i3];
    if (resolvedEntity) {
      entitiesById.set(entityId, resolvedEntity);
      continue;
    }
    const fallbackMemory = missingMessageByEntityId.get(entityId);
    const fallbackEntity = fallbackMemory && buildFormattingFallbackEntity(fallbackMemory);
    if (fallbackEntity) {
      entitiesById.set(entityId, fallbackEntity);
    }
  }
  return Array.from(entitiesById.values());
}
