async function generateContextsInBatch(runtime2, fullDocumentText, chunks, contentType, batchIndices, _documentTitle) {
  if (!chunks || chunks.length === 0) {
    return [];
  }
  const providerLimits = await getProviderRateLimits(runtime2);
  const rateLimiter = createRateLimiter(providerLimits.requestsPerMinute || 60, providerLimits.tokensPerMinute, providerLimits.rateLimitEnabled);
  const config3 = validateModelConfig(runtime2);
  const isUsingOpenRouter = config3.TEXT_PROVIDER === "openrouter";
  const isUsingCacheCapableModel = isUsingOpenRouter && (config3.TEXT_MODEL?.toLowerCase().includes("claude") || config3.TEXT_MODEL?.toLowerCase().includes("gemini"));
  logger.debug(`Contextualizing ${chunks.length} chunks with ${config3.TEXT_PROVIDER}/${config3.TEXT_MODEL} (cache: ${isUsingCacheCapableModel})`);
  const promptConfigs = prepareContextPrompts(chunks, fullDocumentText, contentType, batchIndices, isUsingCacheCapableModel);
  const contextualizedChunks = await Promise.all(promptConfigs.map(async (item) => {
    if (!item.valid) {
      return {
        contextualizedText: item.chunkText,
        success: false,
        index: item.originalIndex
      };
    }
    const llmTokens = estimateTokens(item.chunkText + (item.prompt || ""));
    await rateLimiter(llmTokens);
    try {
      const generateTextOperation = async () => {
        if (useCustomLLM) {
          if (item.usesCaching && item.promptText) {
            return await generateText2(runtime2, item.promptText, item.systemPrompt, {
              cacheDocument: item.fullDocumentTextForContext,
              cacheOptions: { type: "ephemeral" },
              autoCacheContextualRetrieval: true
            });
          } else if (item.prompt) {
            return await generateText2(runtime2, item.prompt);
          }
          throw new Error("Missing prompt for text generation");
        } else {
          if (item.usesCaching && item.promptText) {
            const combinedPrompt = item.systemPrompt ? `${item.systemPrompt}

${item.promptText}` : item.promptText;
            return await runtime2.useModel(ModelType.TEXT_LARGE, {
              prompt: combinedPrompt
            });
          } else if (item.prompt) {
            return await runtime2.useModel(ModelType.TEXT_LARGE, {
              prompt: item.prompt
            });
          }
          throw new Error("Missing prompt for text generation");
        }
      };
      const llmResponse = await withRateLimitRetry(generateTextOperation, `context generation for chunk ${item.originalIndex}`);
      const generatedContext = typeof llmResponse === "string" ? llmResponse : llmResponse.text;
      const contextualizedText = getChunkWithContext(item.chunkText, generatedContext);
      return {
        contextualizedText,
        success: true,
        index: item.originalIndex
      };
    } catch (error49) {
      const errorMessage = error49 instanceof Error ? error49.message : String(error49);
      logger.error(`Error generating context for chunk ${item.originalIndex}: ${errorMessage}`);
      return {
        contextualizedText: item.chunkText,
        success: false,
        index: item.originalIndex
      };
    }
  }));
  return contextualizedChunks;
}
function prepareContextPrompts(chunks, fullDocumentText, contentType, batchIndices, isUsingCacheCapableModel = false) {
  return chunks.map((chunkText2, idx) => {
    const originalIndex = batchIndices ? batchIndices[idx] : idx;
    try {
      if (isUsingCacheCapableModel) {
        const cachingPromptInfo = contentType ? getCachingPromptForMimeType(contentType, chunkText2) : getCachingContextualizationPrompt(chunkText2);
        if (cachingPromptInfo.prompt.startsWith("Error:")) {
          return {
            originalIndex,
            chunkText: chunkText2,
            valid: false,
            usesCaching: false
          };
        }
        return {
          valid: true,
          originalIndex,
          chunkText: chunkText2,
          usesCaching: true,
          systemPrompt: cachingPromptInfo.systemPrompt,
          promptText: cachingPromptInfo.prompt,
          fullDocumentTextForContext: fullDocumentText
        };
      } else {
        const prompt = contentType ? getPromptForMimeType(contentType, fullDocumentText, chunkText2) : getContextualizationPrompt(fullDocumentText, chunkText2);
        if (prompt.startsWith("Error:")) {
          return {
            prompt: null,
            originalIndex,
            chunkText: chunkText2,
            valid: false,
            usesCaching: false
          };
        }
        return {
          prompt,
          originalIndex,
          chunkText: chunkText2,
          valid: true,
          usesCaching: false
        };
      }
    } catch (error49) {
      const errorMessage = error49 instanceof Error ? error49.message : String(error49);
      logger.error(`Error preparing prompt for chunk ${originalIndex}: ${errorMessage}`);
      return {
        prompt: null,
        originalIndex,
        chunkText: chunkText2,
        valid: false,
        usesCaching: false
      };
    }
  });
}
async function generateEmbeddingWithValidation(runtime2, text3) {
  try {
    const embeddingResult = await runtime2.useModel(ModelType.TEXT_EMBEDDING, {
      text: text3
    });
    const embedding = Array.isArray(embeddingResult) ? embeddingResult : embeddingResult?.embedding;
    if (!embedding || embedding.length === 0) {
      return {
        embedding: null,
        success: false,
        error: new Error("Zero vector detected")
      };
    }
    return { embedding, success: true };
  } catch (error49) {
    return {
      embedding: null,
      success: false,
      error: error49 instanceof Error ? error49 : new Error(String(error49))
    };
  }
}
async function withRateLimitRetry(operation, errorContext, retryDelay) {
  try {
    return await operation();
  } catch (error49) {
    const errorWithStatus = error49;
    if (errorWithStatus.status === 429) {
      const delay3 = retryDelay || errorWithStatus.headers?.["retry-after"] || 5;
      await new Promise((resolve4) => setTimeout(resolve4, delay3 * 1000));
      try {
        return await operation();
      } catch (retryError) {
        const retryErrorMessage = retryError instanceof Error ? retryError.message : String(retryError);
        logger.error(`Failed after retry for ${errorContext}: ${retryErrorMessage}`);
        throw retryError;
      }
    }
    throw error49;
  }
}
function createRateLimiter(requestsPerMinute, tokensPerMinute, rateLimitEnabled = true) {
  const requestTimes = [];
  const tokenUsage = [];
  const intervalMs = 60 * 1000;
  return async function rateLimiter(estimatedTokens = 1000) {
    if (!rateLimitEnabled)
      return;
    const now = Date.now();
    while (requestTimes.length > 0 && now - requestTimes[0] > intervalMs) {
      requestTimes.shift();
    }
    while (tokenUsage.length > 0 && now - tokenUsage[0].timestamp > intervalMs) {
      tokenUsage.shift();
    }
    const currentTokens = tokenUsage.reduce((sum, usage) => sum + usage.tokens, 0);
    const requestLimitExceeded = requestTimes.length >= requestsPerMinute;
    const tokenLimitExceeded = tokensPerMinute && currentTokens + estimatedTokens > tokensPerMinute;
    if (requestLimitExceeded || tokenLimitExceeded) {
      let timeToWait = 0;
      if (requestLimitExceeded) {
        timeToWait = Math.max(timeToWait, requestTimes[0] + intervalMs - now);
      }
      if (tokenLimitExceeded && tokenUsage.length > 0) {
        timeToWait = Math.max(timeToWait, tokenUsage[0].timestamp + intervalMs - now);
      }
      if (timeToWait > 0) {
        await new Promise((resolve4) => setTimeout(resolve4, timeToWait));
      }
    }
    requestTimes.push(now);
    if (tokensPerMinute) {
      tokenUsage.push({ timestamp: now, tokens: estimatedTokens });
    }
  };
}

